import{Component}from"@theme/component";class CopyToClipboardComponent extends Component{copyToClipboard(){const o=this.getAttribute("text-to-copy");if(!o)return;navigator.clipboard.writeText(o);const t=this.refs.copySuccessMessage;t instanceof Element&&t.classList.remove("visually-hidden")}}customElements.get("copy-to-clipboard-component")||customElements.define("copy-to-clipboard-component",CopyToClipboardComponent);